<script setup>import{reactive}from'vue';import{ElMessage}from'element-plus';import PageHeader from'../components/PageHeader.vue';const form=reactive({name:'木序定制管理端',phone:'400-888-8888',threshold:30,email:true,system:true,statuses:['待受理','已受理','方案中','生产中','已完成']})</script><template><div class="admin-page"><PageHeader title="系统设置" description="维护平台基础信息、预警规则与通知偏好"><el-button type="primary" @click="ElMessage.success('设置已保存')">保存设置</el-button></PageHeader><div class="settings work-surface"><el-tabs tab-position="left"><el-tab-pane label="基础信息"><h2 class="section-title">平台信息</h2><el-form :model="form" label-width="110px" style="max-width:620px"><el-form-item label="平台名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="服务热线"><el-input v-model="form.phone"/></el-form-item></el-form></el-tab-pane><el-tab-pane label="状态字典"><h2 class="section-title">订单状态</h2><el-tag v-for="x in form.statuses" :key="x" closable style="margin:0 8px 8px 0">{{x}}</el-tag><el-button size="small">新增状态</el-button></el-tab-pane><el-tab-pane label="库存预警"><h2 class="section-title">预警规则</h2><el-form label-width="150px"><el-form-item label="默认安全库存"><el-input-number v-model="form.threshold" :min="0"/> 件</el-form-item></el-form></el-tab-pane><el-tab-pane label="通知设置"><h2 class="section-title">通知偏好</h2><el-form label-width="150px"><el-form-item label="系统内通知"><el-switch v-model="form.system"/></el-form-item><el-form-item label="邮件通知"><el-switch v-model="form.email"/></el-form-item></el-form></el-tab-pane></el-tabs></div></div></template><style scoped>.settings{padding:24px;min-height:520px}.settings :deep(.el-tabs__content){padding:8px 28px}</style>
